export default function ({ playlists, archiveName }) {
  const pick = (n) => {
    const a = playlists.filter((p) => p?.name === n);
    if (a.length !== 1 || typeof a[0].id !== "string" || !a[0].id)
      throw Error("Expected exactly one " + n + " playlist");
    return a[0].id;
  };
  return { discover: pick("Discover Weekly"), archive: pick(archiveName) };
}

