export default function ({ discover, archive, id }) {
  const uri = (x) => {
    const u = x?.track?.uri;
    if (typeof u !== "string" || !u.startsWith("spotify:track:"))
      throw Error("Playlist item has no track URI");
    return u;
  };
  const existing = new Set(archive.map(uri));
  return {
    items: discover
      .map(uri)
      .filter((x) => !existing.has(x))
      .map((uri) => ({ uri })),
    id,
  };
}

