export default function next({ items, id, previousState }) {
  const index = previousState === null ? 0 : previousState.index + 1;
  if (index >= items.length)
    return {
      state: { index },
      more: false,
      id,
      uris: ["-"],
      removeItems: [{ uri: "-" }],
      count: items.length,
    };
  const uri = items[index]?.uri;
  if (typeof uri !== "string" || !uri) throw Error("Invalid track URI");
  return {
    state: { index },
    more: true,
    id,
    uris: [uri],
    removeItems: [{ uri }],
    count: items.length,
  };
}
